import { map } from 'rxjs/operators';
import { del, get, patch, post, put } from '../../api';
import { toQueryString } from '../../utilities/api';
import { Survey } from './model';
/**
 * @private
 */
const PATH = '/api/staff/v1/surveys';
/**
 * Query the available surveys
 * @param query_params Query parameters to add the to request URL
 */
export function querySurveys(query_params = {}) {
    const query = toQueryString(query_params);
    return get(`${PATH}${query ? '?' + query : ''}`).pipe(map((l) => l.map((_) => new Survey(_))));
}
/**
 * Get the data for an survey
 * @param id ID of the survey to retrieve
 * @param query_params Query parameters to add the to request URL
 */
export function showSurvey(id, query_params = {}) {
    const query = toQueryString(query_params);
    return get(`${PATH}/${id}${query ? '?' + query : ''}`).pipe(map((l) => new Survey(l)));
}
/**
 * Update the survey in the database
 * @param id ID of the survey
 * @param form_data New values for the survey
 * @param query_params Query parameters to add the to request URL
 * @param method HTTP verb to use on request. Defaults to `patch`
 */
export function updateSurvey(id, form_data, method = 'patch') {
    return (method === 'put' ? put : patch)(`${PATH}/${id}`, form_data).pipe(map((l) => new Survey(l)));
}
/**
 * Add a new survey to the database
 * @param form_data Survey data
 * @param query_params Query parameters to add the to request URL
 */
export function addSurvey(form_data) {
    return post(`${PATH}`, form_data).pipe(map((l) => new Survey(l)));
}
/**
 * Remove an survey from the database
 * @param id ID of the survey
 * @param query_params Query parameters to add the to request URL
 */
export function removeSurvey(id, query_params = {}) {
    const query = toQueryString(query_params);
    return del(`${PATH}/${id}${query ? '?' + query : ''}`);
}
